/**
 * Scene resolution: the only place a save is actually changed.
 *
 * Every tool funnels through `resolve` or `advance`. That single choke point is
 * what makes the model safe to let loose: it can describe anything, but state
 * only moves here, and only through validated branches.
 *
 * Two scene kinds, matching the two decision types in adjudicate.js:
 *
 *   kind: "moral"   the player picks one of the declared options. NO DICE.
 *                   Effects come from data/acts.json, verbatim.
 *   kind: "ability" one declared attempt against a difficulty. DICE.
 *                   Success/failure effects come from the scene data.
 *
 * A scene may also be `free`: no options, no check, just a situation the model
 * narrates. Used for interludes and for the player's own inventions.
 */

import { applyEffects, check, weigh, clampDifficulty, clampAttribute, COUNTER_KEYS, RESOURCE_KEYS } from './adjudicate.js'
import { priceChoice, decay } from './destiny.js'
import { advance as advanceClock } from './clock.js'
import { ensurePerson, putPerson, remember, dispositionOf } from './people.js'
import { advanceFactions, syncPlayerFaction, powerModifier, INITIAL_FACTIONS } from './world.js'
import { driftMoods } from './people.js'

/** The year the world starts moving on its own. */
export const HISTORY_START_YEAR = 184

/** Maximum number of log entries kept in the save. History file keeps the rest. */
const LOG_LIMIT = 200

/** Push one log entry, trimming to the cap. */
export function pushLog(state, entry) {
  const log = Array.isArray(state.log) ? state.log : []
  const next = [...log, { turn: state.clock?.turn ?? 0, year: state.clock?.year ?? 184, ...entry }]
  return { ...state, log: next.slice(Math.max(0, next.length - LOG_LIMIT)) }
}

/** Flatten data/acts.json into a lookup by act id. */
export function indexActs(document) {
  const byId = new Map()
  for (const act of document?.acts ?? []) {
    byId.set(act.id, act)
  }
  return byId
}

/** Find one scene inside an act. Returns null when either is missing. */
export function findScene(act, sceneId) {
  if (act === null || act === undefined) return null
  const scenes = Array.isArray(act.scenes) ? act.scenes : []
  if (sceneId === undefined || sceneId === null) {
    return scenes[0] ?? null
  }
  return scenes.find((scene) => scene.id === sceneId) ?? null
}

/** The scene the save is currently sitting on. */
export function currentScene(state, acts) {
  const act = acts.get(state.act)
  const scenes = Array.isArray(act?.scenes) ? act.scenes : []
  const index = Number.isFinite(state.scene) ? state.scene : 0
  return { act, scene: scenes[index] ?? null, index, total: scenes.length }
}

/**
 * If the current scene is stamped with `atAge` and the player is younger, the
 * clock must catch up before the scene can be played.
 *
 * This exists because the first act is a CHILDHOOD: the mulberry tree is a
 * five-year-old, 师事卢植 is fifteen, and starting the clock at 23 with a birth
 * clock of 161 produced a 23-year-old boy pointing at a tree he had already
 * outgrown. Scenes without `atAge` inherit the act's window and never trigger
 * this.
 *
 * @returns {{ state, moved: number, targetAge: number }|null} null when no move is needed
 */
export function catchUpToScene(state, acts) {
  const { scene } = currentScene(state, acts)
  const target = Number.isFinite(scene?.atAge) ? scene.atAge : null
  if (target === null) return null
  const current = Number.isFinite(state.age) ? state.age : 0
  if (current >= target) return null
  const turns = Math.max(1, (target - current) * 4)
  const advanced = advanceWorld(state, turns)
  return { state: advanced.state, moved: turns, targetAge: target, events: advanced.events }
}

/**
 * Effects of a moral branch, with the historical/departure bookkeeping applied.
 *
 * Note what this does NOT do: it does not block a departure, does not warn the
 * player off, and does not rewrite the choice. It prices it in `drift` and
 * records it in the log. The world's response is a later consequence, not a
 * refusal now.
 */
export function chooseBranch(state, act, scene, branchId) {
  const options = Array.isArray(scene.options) ? scene.options : []
  const branch = options.find((option) => option.id === branchId)
  if (branch === undefined) {
    throw new Error(
      `「${scene.title}」没有这个选项：${branchId}。可选：${options.map((o) => o.id).join(' / ')}`
    )
  }

  const priced = priceChoice({
    node: { freeChoice: scene.freeChoice === true },
    branch,
    state,
    resources: {
      troops: state.player?.resources?.troops ?? 0,
      gold: state.player?.resources?.gold ?? 0,
      grain: state.player?.resources?.grain ?? 0
    }
  })

  const resources = { ...(state.player?.resources ?? {}) }
  const counters = { ...(state.player?.counters ?? {}) }

  // One effects object in acts.json mixes counters and resources, so each bag is
  // written with an explicit key list. See applyEffects for why.
  applyEffects(counters, branch.effects, COUNTER_KEYS)
  applyEffects(resources, branch.effects, RESOURCE_KEYS)

  const attrs = { ...(state.player?.attrs ?? {}) }
  if (branch.attributeGain !== undefined && typeof branch.attributeGain === 'object') {
    for (const key of Object.keys(branch.attributeGain)) {
      const gain = Number(branch.attributeGain[key])
      if (!Number.isFinite(gain)) continue
      const current = Number.isFinite(attrs[key]) ? attrs[key] : 0
      attrs[key] = Math.min(100, Math.max(0, current + Math.trunc(gain)))
    }
  }

  let next = {
    ...state,
    drift: priced.drift,
    player: {
      ...state.player,
      attrs,
      counters,
      resources: {
        ...resources,
        // Resources are physical; never let a moral choice make them negative.
        gold: Math.max(0, Math.trunc(resources.gold ?? 0)),
        grain: Math.max(0, Math.trunc(resources.grain ?? 0)),
        troops: Math.max(0, Math.trunc(resources.troops ?? 0)),
        hp: Math.min(100, Math.max(0, Math.trunc(resources.hp ?? 100)))
      }
    },
    counters: {
      ...(state.counters ?? {}),
      choicesMade: (state.counters?.choicesMade ?? 0) + 1,
      deviations: (state.counters?.deviations ?? 0) + (priced.departure ? 1 : 0)
    }
  }

  // Titles and flags a branch can grant. Kept data-driven so acts.json stays the
  // single source of truth for what a choice unlocks.
  if (typeof branch.grantTitle === 'string' && branch.grantTitle.length > 0) {
    const titles = Array.isArray(next.player.titles) ? next.player.titles : []
    if (!titles.includes(branch.grantTitle)) {
      next = { ...next, player: { ...next.player, titles: [...titles, branch.grantTitle] } }
    }
  }
  if (branch.setsFlag !== undefined && typeof branch.setsFlag === 'object') {
    next = { ...next, flags: { ...(next.flags ?? {}), ...branch.setsFlag } }
  }
  if (typeof branch.rememberBy === 'string' && branch.rememberBy.length > 0) {
    const seeded = ensurePerson(next, branch.rememberBy, 0)
    next = seeded.state
    const updated = remember(seeded.person, {
      kind: branch.memoryKind ?? 'kindness',
      text: branch.memoryText ?? branch.label,
      turn: next.clock?.turn ?? 0
    })
    next = putPerson(next, updated)
  }

  next = pushLog(next, {
    kind: 'choice',
    act: act?.id ?? '',
    scene: scene.id,
    text: branch.note.length > 0 ? `${branch.label}——${branch.note}` : branch.label,
    departure: priced.departure,
    drift: priced.drift
  })

  return {
    state: next,
    branch,
    priced,
    effects: branch.effects ?? {},
    attributeGain: branch.attributeGain ?? null
  }
}

/**
 * Resolve an ability scene against a die roll.
 *
 * The difficulty comes from the scene data, adjusted by:
 *   · the model's hint, CLAMPED to the legal band (it may say "hard", never
 *     "impossible");
 *   · engine modifiers derived from state (power gap, drift pressure).
 * The model's hint can move the number by at most its clamp window; it can
 * never make success automatic.
 */
export function attemptScene(state, act, scene, hint) {
  const attribute = clampAttribute(hint?.attribute ?? scene.attribute, scene.attribute ?? 'mei')
  const difficulty = clampDifficulty(
    Number.isFinite(hint?.difficulty) ? hint.difficulty : scene.difficulty,
    scene.difficulty ?? 50
  )

  const modifiers = []
  const targetFaction = scene.targetFaction
  if (typeof targetFaction === 'string') {
    const mine = state.factions?.liubei?.power ?? 0
    const theirs = state.factions?.[targetFaction]?.power ?? 0
    const value = powerModifier(mine, theirs)
    if (value !== 0) {
      modifiers.push({ value, reason: `敌我之势（${theirs} vs ${mine}）` })
    }
  }
  const driftValue = Number.isFinite(state.drift) ? state.drift : 0
  if (driftValue > 0) {
    modifiers.push({
      value: -Math.min(30, Math.round(driftValue * 0.35)),
      reason: '天下侧目'
    })
  }

  const result = check({
    state: state.rng ?? 0,
    attrs: state.player?.attrs ?? {},
    attribute,
    difficulty,
    modifiers
  })

  const effects = result.outcome === 'success' || result.outcome === 'critical_success'
    ? scene.effects?.success ?? {}
    : scene.effects?.failure ?? {}

  const resources = { ...(state.player?.resources ?? {}) }
  const counters = { ...(state.player?.counters ?? {}) }
  applyEffects(counters, effects, COUNTER_KEYS)
  applyEffects(resources, effects, RESOURCE_KEYS)

  let next = {
    ...state,
    rng: result.state,
    drift: decay(state).drift,
    player: {
      ...state.player,
      counters,
      resources: {
        ...resources,
        gold: Math.max(0, Math.trunc(resources.gold ?? 0)),
        grain: Math.max(0, Math.trunc(resources.grain ?? 0)),
        troops: Math.max(0, Math.trunc(resources.troops ?? 0)),
        hp: Math.min(100, Math.max(0, Math.trunc(resources.hp ?? 100)))
      }
    },
    counters: { ...(state.counters ?? {}), choicesMade: (state.counters?.choicesMade ?? 0) + 1 }
  }

  const text = result.outcome === 'success' || result.outcome === 'critical_success'
    ? scene.successText ?? ''
    : scene.failureText ?? ''

  next = pushLog(next, {
    kind: 'check',
    act: act?.id ?? '',
    scene: scene.id,
    text,
    outcome: result.outcome,
    roll: result.roll,
    margin: result.margin
  })

  return { state: next, result, effects, text }
}

/**
 * Advance the world by `turns` seasons without resolving a scene.
 *
 * This is the "world does not wait" path: factions move, moods drift, the clock
 * runs, and the drift decays a little because nothing provocative happened.
 */
export function advanceWorld(state, turns = 1) {
  let next = state
  const events = []
  const step = Math.max(1, Math.trunc(turns))

  for (let index = 0; index < step; index += 1) {
    const clock = advanceClock(next.clock, 1)
    next = {
      ...next,
      clock,
      age: clock.age,
      counters: { ...(next.counters ?? {}), turnsPlayed: (next.counters?.turnsPlayed ?? 0) + 1 }
    }
    // The world only starts turning in 184, when the Yellow Turban rising makes
    // the warlords matter. Before that these are just childhood years: moving
    // the clock through them must not simulate thirty seasons of faction growth
    // that the player could not possibly have influenced.
    if (clock.year < HISTORY_START_YEAR) {
      continue
    }
    const advanced = advanceFactions(next)
    next = advanced.state
    events.push(...advanced.events)
    next = driftMoods(next)
    next = { ...next, drift: decay(next).drift }
  }

  next = syncPlayerFaction(next)

  // One line per faction per advance, not per season.
  //
  // A multi-season advance loops the seasonal step several times, so the same
  // faction can cross two bands inside one call and produce "公孙瓒之势渐衰（10 → 5）"
  // immediately followed by "公孙瓒之势渐衰（5 → 0）". Both are true; together
  // they read as a stutter. Keeping the LAST line per faction reports where it
  // ended up, which is what a chronicle entry for that span would say.
  const lastByFaction = new Map()
  const ordered = []
  for (const event of events) {
    const key = event.faction ?? event.text
    if (lastByFaction.has(key)) {
      const index = ordered.indexOf(lastByFaction.get(key))
      ordered.splice(index, 1)
    }
    lastByFaction.set(key, event)
    ordered.push(event)
  }

  for (const event of ordered) {
    next = pushLog(next, { kind: 'world', text: event.text })
  }
  return { state: next, events: ordered }
}

/**
 * Move the cursor to the next scene, or to the next act when this one is done.
 *
 * Acts are strictly sequential: skipping one would silently delete a chapter of
 * the life, which is the one thing this game is about. So when the player
 * reaches an act they are too YOUNG for (they rushed, or a hand-edited save is
 * out of step), the engine FAST-FORWARDS the clock to the act's opening age
 * instead of skipping the act. Narratively that is exactly what happened to Liu
 * Bei for twenty years: nothing, then the next thing.
 */
export function nextCursor(state, acts) {
  const act = acts.get(state.act)
  const scenes = Array.isArray(act?.scenes) ? act.scenes : []
  const index = Number.isFinite(state.scene) ? state.scene : 0
  if (index + 1 < scenes.length) {
    return { ...state, scene: index + 1 }
  }
  const order = Array.from(acts.keys())
  const position = order.indexOf(state.act)
  const candidate = acts.get(order[position + 1])
  if (candidate === undefined) {
    return { ...state, act: 'end', scene: 0 }
  }

  let next = { ...state, act: candidate.id, actName: candidate.name, scene: 0, place: candidate.place }
  const ageFrom = Number.isFinite(candidate.ageFrom) ? candidate.ageFrom : 0
  const currentAge = Number.isFinite(next.age) ? next.age : 0
  if (currentAge < ageFrom) {
    // Seasons, not years: one year is four turns, and the clock floors, so one
    // extra turn guarantees the age actually crosses the threshold.
    const turns = (ageFrom - currentAge) * 4
    next = advanceWorld(next, Math.max(1, turns)).state
    next = { ...next, act: candidate.id, actName: candidate.name, scene: 0, place: candidate.place }
  }
  return next
}

/**
 * Summarise one scene for the model: everything it may narrate, and nothing it
 * may invent. Options are returned with their declared effects so the model can
 * present a fair comparison without guessing what each costs.
 */
export function describeScene(act, scene, state) {
  if (scene === null) {
    return null
  }
  const base = {
    act: act?.name ?? '',
    actId: act?.id ?? '',
    sceneId: scene.id,
    title: scene.title,
    narration: scene.narration,
    kind: scene.kind,
    historical: scene.historical ?? ''
  }
  if (scene.kind === 'moral') {
    const options = weigh(scene.options ?? []).map((option, index) => ({
      index: index + 1,
      id: option.id,
      label: option.label,
      effects: option.effects,
      note: option.note
    }))
    return { ...base, options }
  }
  if (scene.kind === 'ability') {
    return {
      ...base,
      attribute: scene.attribute,
      difficulty: scene.difficulty,
      targetFaction: scene.targetFaction ?? ''
    }
  }
  return base
}

/** Current disposition of everyone the player has met, for the people tool. */
export function rosterOf(state) {
  const people = state.people ?? {}
  return Object.keys(people)
    .map((id) => {
      const person = people[id]
      return {
        id,
        name: person.name,
        courtesy: person.courtesy,
        mood: person.mood,
        disposition: dispositionOf(person),
        met: person.met === true,
        memories: (person.memories ?? []).map((memory) => memory.text)
      }
    })
    .sort((a, b) => Math.abs(b.disposition) - Math.abs(a.disposition))
}

/** Bootstrap the faction table onto a fresh save. */
export function seedFactions(state) {
  if (state.factions !== undefined) {
    return state
  }
  return { ...state, factions: JSON.parse(JSON.stringify(INITIAL_FACTIONS)) }
}
